on conflict (chave) do update set dados = excluded.dados, origem = excluded.origem, em = now();

do $$
declare v jsonb;
begin
  if exists (select 1 from public.marcas where slug = 'hamburgueria-pomerode') then
    v := private.importar_cardapio('hamburgueria-pomerode', (select dados from private.cardapios_importados where chave = 'hamburgueria-pomerode'));
    raise notice 'HAMBURGUERIA POMERODE importada: %', v;
  else
    raise notice 'Marca hamburgueria-pomerode não existe neste banco: nada importado.';
  end if;
end $$;

-- conferência: mostra o resultado no SQL Editor
select c.nome as categoria, count(*) filter (where pm.ativo) as produtos_ativos
  from public.setores c
  join private.importacoes i on i.alvo = c.id
  join public.produtos p on p.setor_id = c.id
  join public.produto_marcas pm on pm.produto_id = p.id and pm.marca_id = (select id from public.marcas where slug = 'hamburgueria-pomerode')
 group by c.nome, c.ordem order by c.ordem;
